function crohnForm(){const root=sheet('Crohn’s treatment'),form=make('form',undefined,root);const t=field(form,'Treatment, as the doctor wrote it','textarea',care().crohn?.treatment??'');t.maxLength=200;t.dir='auto';
 const status=make('p','',form,'personal-status');const row=make('div',undefined,form,'personal-actions');const b=make('button','Save',row,'primary');b.type='submit';
 form.onsubmit=async ev=>{ev.preventDefault();b.disabled=true;try{await run(()=>ctx.command('care.crohn.save',{treatment:t.value}),status);dialog?.close();}catch(e){status.textContent=e.message;b.disabled=false;}};}
function openHistory(kinds){const c=care(),root=sheet(kinds?'Belly history':'History');const all=[...c.entries];const body=make('div',undefined,root);const foot=make('div',undefined,root);let more=c.olderEntries;
 const paint=()=>{body.replaceChildren();foot.replaceChildren();const list=all.filter(e=>!kinds||kinds.includes(e.kind));if(!list.length)make('p','Nothing logged yet.',body,'personal-muted');drawHistory(body,list);if(more){const b=button('Load older',foot,async()=>{b.disabled=true;try{const last=all.at(-1);const query=last?'?before='+last.occurredAt+'&beforeId='+encodeURIComponent(last.id):'';const r=await ctx.api('care/history'+query);all.push(...r.entries);more=r.more;paint();}catch(err){b.disabled=false;ctx.error(err);}});}make('p','Times are in '+zoneName()+'.',foot,'personal-muted');};paint();}
function drawHistory(root,list){const c=care();
 let day=null,box=null;for(const e of list){const d=localDay(e.occurredAt);if(d!==day){day=d;make('h3',d===c.today?'Today':fmtDay(d),root);box=make('div',undefined,root,'care-history');}
  const row=make(e.canEdit?'button':'div',undefined,box,'care-history-row');if(e.canEdit){row.type='button';row.onclick=()=>entryForm(e.kind,e);}
  make('span',fmtTime(e.occurredAt),row,'care-history-time');const txt=make('span',undefined,row);make('strong',describe(e),txt).dir='auto';const by=make('small','by '+e.loggedBy+(e.source?' · '+e.source:'')+(Math.abs(e.loggedAt-e.occurredAt)>600000?' · logged '+when(e.loggedAt):'')+(e.edited?' · edited':'')+(e.visibility==='private'?' · only you':''),txt);by.dir='auto';}
 }
function labChart(root,t){const latest=t.latest;if(!latest)return;const readings=t.readings.filter(r=>r.verified&&r.unit.trim().toLowerCase()===latest.unit.trim().toLowerCase()&&Number.isFinite(r.value)).sort((a,b)=>a.date.localeCompare(b.date)).slice(-12);if(readings.length<2)return;const card=make('div',undefined,root,'care-lab-chart');make('small',t.test.toUpperCase()+' · '+latest.unit,card);make('div',latest.valueText+' · '+fmtDate(latest.date),card,'care-lab-chart-current');const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 300 100');svg.setAttribute('role','img');svg.setAttribute('aria-label',t.test+' readings over time');card.append(svg);const vals=readings.map(r=>r.value),lo=Math.min(...vals),hi=Math.max(...vals),spread=hi-lo||1;const points=readings.map((r,i)=>({x:15+i*270/(readings.length-1),y:80-(r.value-lo)/spread*60,r}));const line=document.createElementNS(ns,'polyline');line.setAttribute('points',points.map(p=>p.x+','+p.y).join(' '));line.setAttribute('fill','none');line.setAttribute('stroke','#e7a3bc');line.setAttribute('stroke-width','2');svg.append(line);for(const p of points){const dot=document.createElementNS(ns,'circle');dot.setAttribute('cx',p.x);dot.setAttribute('cy',p.y);dot.setAttribute('r','4');dot.setAttribute('fill','#e7a3bc');const title=document.createElementNS(ns,'title');title.textContent=fmtDate(p.r.date)+': '+p.r.valueText+' '+p.r.unit;dot.append(title);svg.append(dot);}const labels=make('div',undefined,card,'care-row');make('small',fmtDate(readings[0].date),labels);make('small',fmtDate(readings.at(-1).date),labels);}
function openMedicalFile(){const c=care(),root=sheet('Medical file');make('p','A summary of the information recorded in Care. Check original documents with the doctor.',root,'personal-muted');make('h3','Medicines',root);if(!c.meds.length)make('p','No medicines recorded yet.',root,'personal-muted');for(const m of c.meds){const box=make('article',undefined,root,'care-lab');make('strong',m.name,box);make('small',[m.dose,m.active?'Active':'Stopped or not started',m.notes].filter(Boolean).join(' · '),box);}make('h3','Lab results',root);const verified=c.labs.filter(t=>t.latest);if(!verified.length)make('p','No verified lab results yet.',root,'personal-muted');for(const t of verified){const box=make('article',undefined,root,'care-lab');make('strong',t.test,box);make('span',t.latest.valueText+' '+t.latest.unit+' · '+fmtDate(t.latest.date),box);make('small','Range on sheet: '+range(t.latest),box);}button('Open all lab results',root,openLabs);make('p','Documents, doctor visits and visit summaries are not yet available in Care.',root,'personal-muted');}
function openLabs(){const c=care(),root=sheet('Labs');const bar=make('div',undefined,root,'personal-actions');button('＋ Add a result',bar,()=>labForm(),'primary');button('Import a lab file',bar,importLabs);
 make('p','Values and H/L exactly as printed on each sheet. Green = moving toward the lab’s range, orange = moving away. The doctor decides what it means.',root,'personal-muted');
 const chartTest=c.labs.find(t=>t.key==='hemoglobin'&&t.latest)||c.labs.find(t=>t.latest&&t.readings.filter(r=>r.verified&&r.unit===t.latest.unit).length>1);if(chartTest)labChart(root,chartTest);
 let group=null;for(const t of c.labs){if(t.group!==group){group=t.group;make('h3',group,root);}const card=make('article',undefined,root,'care-lab');const top=make('div',undefined,card,'care-row');make('strong',t.test,top).dir='auto';if(t.latest)statusChip(t,top);const ab=aboutTest(t.key);if(ab)make('p',ab,card,'care-about');
  if(t.latest){const l=t.latest;const v=make('div',undefined,card,'care-lab-value');make('span',l.valueText,v,'care-lab-num');make('span',' '+l.unit+(l.flag?' · '+l.flag+' on sheet':''),v);const [tx,cls]=trendText(t);make('span',tx,card,'care-trend '+cls);make('small',fmtDate(l.date)+' · range '+range(l)+(t.previous?' · was '+t.previous.valueText+' on '+fmtDate(t.previous.date):''),card);}
  if(t.unverified){const u=make('p',t.unverified+' unverified · check against the sheet',card,'care-unverified');for(const r of t.readings.filter(r=>!r.verified))button('Verify '+r.valueText+' · '+fmtDate(r.date),u,()=>labForm(t,r));}
  const more=make('details',undefined,card);make('summary','All readings · '+t.readings.length,more);for(const r of t.readings){const b=button(fmtDate(r.date)+' · '+r.valueText+' '+r.unit+(r.flag?' '+r.flag:'')+(r.verified?'':' · unverified'),more,()=>labForm(t,r),'care-reading');b.dir='auto';}}
 if(!c.labs.length)make('p','No results yet.',root,'personal-muted');}
function labForm(t,r){const root=sheet(r?'Edit result':'Add a lab result'),form=make('form',undefined,root);const test=field(form,'Test name','text',r?t.test:'');test.required=true;test.maxLength=60;const value=field(form,'Result, exactly as printed','text',r?.valueText??'');value.required=true;value.inputMode='decimal';const unit=field(form,'Unit','text',r?.unit??'');const lo=field(form,'Normal range from · optional','text',r?.lo??'');lo.inputMode='decimal';const hi=field(form,'Normal range to · optional','text',r?.hi??'');hi.inputMode='decimal';const rt=field(form,'Range as printed · optional','text',r?.rangeText??'');const flag=chips(form,'Flag printed on the sheet',[['H','H'],['L','L']],r?.flag?[r.flag]:[]);const date=field(form,'Result date','date',r?.date??'');date.required=true;const group=field(form,'Group','text',r?(t.group):'Blood picture');const source=field(form,'Source · optional','text',r?.source??'');const l=make('label',undefined,form,'personal-check'),ver=make('input',undefined,l);ver.type='checkbox';ver.checked=r?r.verified:true;make('span','I checked this against the sheet',l);
 const status=make('p','',form,'personal-status');const row=make('div',undefined,form,'personal-actions');const b=make('button','Save',row,'primary');b.type='submit';if(r)button('Delete',row,async()=>{if(!confirm('Delete this result?'))return;try{await run(()=>ctx.command('care.lab.delete',{id:r.id,revision:r.revision}),status);dialog.close();}catch{}});
 const n=v=>v===''||v===null?null:Number(String(v).replace(',','.'));
 form.onsubmit=async ev=>{ev.preventDefault();b.disabled=true;try{await run(()=>ctx.command('care.lab.save',{...(r?{id:r.id,revision:r.revision}:{}),test:test.value,value:n(value.value),valueText:value.value,unit:unit.value,lo:n(lo.value),hi:n(hi.value),rangeText:rt.value,flag:flag()[0]??'',date:date.value,group:group.value,source:source.value,verified:ver.checked}),status);openLabs();}catch(e){status.textContent=e.message;b.disabled=false;}};}
function importLabs(){const root=sheet('Import lab results');make('p','Choose a .json lab file prepared from the sheets. Results already saved for the same test and date are skipped.',root,'personal-muted');const input=make('input',undefined,root);input.type='file';input.accept='application/json,.json';const status=make('p','',root,'personal-status');status.setAttribute('role','status');
 input.onchange=async()=>{const file=input.files[0];if(!file)return;try{const data=JSON.parse(await file.text());const labs=Array.isArray(data)?data:data.labs??[],steps=Array.isArray(data)?[]:data.milestones??[];status.textContent='Importing…';const out=[];if(labs.length){const r=await run(()=>ctx.command('care.labs.import',{labs}),status);out.push(r.added+' lab results'+(r.skipped?' (skipped '+r.skipped+' already saved)':''));}if(steps.length){const r=await run(()=>ctx.command('care.milestones.import',{milestones:steps}),status);out.push(r.added+' story steps'+(r.skipped?' (skipped '+r.skipped+')':''));}status.textContent=out.length?'Added '+out.join(' · ')+'.':'Nothing to import in this file.';}catch(e){status.textContent=e.message;}};}
function openMeds(){const c=care(),root=sheet('Medicines');button('＋ Add a medicine',make('div',undefined,root,'personal-actions'),()=>medForm(),'primary');const days=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
 for(const m of c.meds){const card=make('article',undefined,root,'care-lab');const top=make('div',undefined,card,'care-row');make('strong',m.name,top).dir='auto';if(m.stoppedOn&&!m.active)make('span','Stopped',top,'care-chip muted');else if(!m.active)make('span','Starts '+fmtDate(m.startedOn),top,'care-chip muted');else if(m.scheduledToday)make('span',m.doneToday?'Done today':'Due today',top,'care-chip '+(m.doneToday?'ok':'warn'));make('small',[m.dose,m.schedule==='daily'?'Daily '+m.times.join(', '):m.schedule==='weekly'?'Weekly · '+days[m.weekday]+(m.times.length?' '+m.times.join(', '):''):'As needed',m.startedOn?'since '+fmtDate(m.startedOn):'',m.lastDose?'last taken '+when(m.lastDose):''].filter(Boolean).join(' · '),card);if(m.notes)make('p',m.notes,card,'personal-muted').dir='auto';const row=make('div',undefined,card,'personal-actions');if(m.active)button('Log dose',row,()=>entryForm('dose',null,{med:m.id}));button('Edit',row,()=>medForm(m));if(!m.stoppedOn)button('Stop',row,async()=>{if(!confirm('Mark '+m.name+' as stopped today?'))return;await run(()=>ctx.command('care.med.stop',{id:m.id,revision:m.revision,stoppedOn:c.today}));openMeds();});}
 if(!c.meds.length)make('p','No medicines yet. Add each one with its dose and times from the prescription.',root,'personal-muted');}
function medForm(m){const root=sheet(m?'Edit medicine':'Add a medicine'),form=make('form',undefined,root);const name=field(form,'Name','text',m?.name??'');name.required=true;const dose=field(form,'Dose · as on the prescription','text',m?.dose??'');const sched=chips(form,'How often',[['daily','Daily'],['weekly','Weekly'],['as-needed','As needed']],[m?.schedule??'daily'],false,true);const times=field(form,'Times, e.g. 09:00, 21:00 · '+zoneName(),'text',(m?.times??[]).join(', '));const wd=chips(form,'Day of week · weekly only',[['0','Sun'],['1','Mon'],['2','Tue'],['3','Wed'],['4','Thu'],['5','Fri'],['6','Sat']],m?.weekday!==null&&m?.weekday!==undefined?[String(m.weekday)]:[]);const started=field(form,'Started on · optional','date',m?.startedOn??'');const notes=field(form,'Notes · optional, e.g. 2 hours after food','textarea',m?.notes??'');notes.maxLength=300;const source=field(form,'Source · optional','text',m?.source??'');
 const status=make('p','',form,'personal-status');const row=make('div',undefined,form,'personal-actions');const b=make('button','Save',row,'primary');b.type='submit';
 form.onsubmit=async ev=>{ev.preventDefault();b.disabled=true;try{await run(()=>ctx.command('care.med.save',{...(m?{id:m.id,revision:m.revision}:{}),name:name.value,dose:dose.value,schedule:sched()[0],times:times.value.split(/[,\s]+/).filter(Boolean),weekday:wd().length?Number(wd()[0]):null,startedOn:started.value,notes:notes.value,source:source.value}),status);openMeds();}catch(e){status.textContent=e.message;b.disabled=false;}};}
let lastWire='';
window.OurCare={fromHistory(state){if(dialog&&!state?.careSheet){sheetFromHistory=true;dialog.close();}if(state?.placeTab==='care'){view=state.careView||'home';saveView();}},
 init(c){ctx=c;},sync(s){st=s;const wire=JSON.stringify([s?.who,s?.care]);if(wire===lastWire)return;lastWire=wire;if(!$('#care')?.hidden)render();},tab(next){if(next!=='care')return;if(!restored){restored=true;let v='home';try{v=sessionStorage.getItem('our-place:care-view')||'home';}catch{}if(['story','guide'].includes(v)&&!history.state?.careView){view='home';history.replaceState({placeTab:'care'},'');view=v;history.pushState({placeTab:'care',careView:v},'');}}render();},reset(){epoch++;st=null;view='home';restored=false;guideFocus=null;try{sessionStorage.removeItem('our-place:care-view');}catch{}lastWire='';dialog?.close();$('#care')?.replaceChildren();}};
